public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Basic validation
    if (n <= 0 || start == null || end == null || start.length != n || end.length != n) {
        return "cannot be travelled";
    }
    // If start equals end, travel is trivially possible
    boolean same = true;
    for (int i = 0; i < n; i++) {
        if (start[i] != end[i]) {
            same = false;
            break;
        }
    }
    if (same) {
        return "can be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    java.util.function.Function<int[], String> coordToKey = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };

    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);

    if (paths == null || paths.length == 0) {
        return "cannot be travelled";
    }

    for (int[] path : paths) {
        if (path == null || path.length != 2 * n) {
            // Invalid path entry; skip or treat as error
            continue;
        }
        int[] coordA = new int[n];
        int[] coordB = new int[n];
        System.arraycopy(path, 0, coordA, 0, n);
        System.arraycopy(path, n, coordB, 0, n);
        String keyA = coordToKey.apply(coordA);
        String keyB = coordToKey.apply(coordB);
        graph.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
        graph.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
    }

    // If start or end not in graph, cannot travel
    if (!graph.containsKey(startKey) || !graph.containsKey(endKey)) {
        return "cannot be travelled";
    }

    // BFS
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = graph.getOrDefault(current, java.util.Collections.emptyList());
        for (String neighbor : neighbors) {
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        return null;
    }
    try {
        String[] parts = date.trim().split("\\s+");
        if (parts.length != 3) {
            return null;
        }
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
        java.time.format.DateTimeFormatter formatter = java.time.format.DateTimeFormatter.ofPattern("MMMM d, yyyy");
        String formattedDate = localDate.format(formatter);
        java.time.DayOfWeek dow = localDate.getDayOfWeek();
        String weekday = dow.getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        return formattedDate + " is a " + weekday;
    } catch (Exception e) {
        return null;
    }
}

public int[] twoSum(int[] nums, int target) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    if (nums.length < 2) {
        throw new IllegalArgumentException("Input array must contain at least two elements");
    }
    java.util.Map<Integer, Integer> map = new java.util.HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (map.containsKey(complement)) {
            return new int[]{map.get(complement), i};
        }
        if (!map.containsKey(nums[i])) {
            map.put(nums[i], i);
        }
    }
    throw new IllegalStateException("No two-sum solution found");
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        // Determine which side is sorted
        if (nums[left] <= nums[mid]) { // left side is sorted
            if (nums[left] <= target && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else { // right side is sorted
            if (nums[mid] < target && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = arr.length;
    if (n == 0) {
        throw new IllegalArgumentException("Input array cannot be empty");
    }
    // Number of elements to trim from each side (5% of n)
    int trimCount = n / 20; // floor of 5% of n
    // If trimCount is zero, no trimming is needed
    if (trimCount == 0) {
        long total = 0;
        for (int val : arr) {
            total += val;
        }
        return (double) total / n;
    }
    // Sort the array to identify smallest and largest elements
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    long sum = 0;
    for (int i = trimCount; i < n - trimCount; i++) {
        sum += sorted[i];
    }
    int remaining = n - 2 * trimCount;
    return (double) sum / remaining;
}

public boolean canArrange(int[] arr, int k) {
    // Validate input
    if (arr == null || k <= 0 || arr.length % 2 != 0) {
        return false;
    }

    int n = arr.length;
    int[] freq = new int[k];

    // Count remainders
    for (int num : arr) {
        int r = ((num % k) + k) % k; // handle negative numbers
        freq[r]++;
    }

    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }

    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // when k is even and r == k/2
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Basic input validation
    if (n <= 0 || edges == null || hasApple == null || hasApple.length != n) {
        return 0;
    }

    // Build adjacency list for the tree
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        if (edge == null || edge.length != 2) {
            continue; // skip malformed edges
        }
        int u = edge[0];
        int v = edge[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            continue; // skip out-of-bounds indices
        }
        graph[u].add(v);
        graph[v].add(u);
    }

    // Depth-first search to compute time needed for each subtree
    int dfs(int node, int parent) {
        int time = 0;
        for (int child : graph[node]) {
            if (child == parent) {
                continue;
            }
            int childTime = dfs(child, node);
            if (childTime > 0 || hasApple[child]) {
                time += childTime + 2; // go to child and back
            }
        }
        return time;
    }

    // Start DFS from root node 0
    return dfs(0, -1);
}

