public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    // Use sets to store achievable sums for each subset size
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] sumsBySize = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        sumsBySize[i] = new java.util.HashSet<>();
    }
    sumsBySize[0].add(0);
    for (int num : nums) {
        // iterate sizes in reverse to avoid using updated values in same iteration
        for (int size = n - 1; size >= 0; size--) {
            if (sumsBySize[size].isEmpty()) continue;
            java.util.HashSet<Integer> currentSet = sumsBySize[size];
            java.util.HashSet<Integer> nextSet = sumsBySize[size + 1];
            for (int s : currentSet) {
                nextSet.add(s + num);
            }
        }
    }
    // Check for any valid subset size k
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (sumsBySize[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    // Handle null or empty input
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    // dp0 represents min cost to reach step i-2, dp1 to reach step i-1
    int dp0 = 0; // cost to reach step -1 (virtual start)
    int dp1 = 0; // cost to reach step 0
    for (int i = 2; i <= n; i++) {
        int costFromPrev = dp1 + cost[i - 1];
        int costFromPrevPrev = dp0 + cost[i - 2];
        int dp2 = Math.min(costFromPrev, costFromPrevPrev);
        dp0 = dp1;
        dp1 = dp2;
    }
    return dp1;
}

