}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    // If k is too large, 2^k would exceed int range or array size
    if (k > 20) { // 2^20 = 1,048,576, which is a safe upper bound for typical constraints
        return false;
    }
    int total = 1 << k; // number of possible binary strings of length k
    if (s.length() < total) {
        return false;
    }
    int mask = total - 1;
    boolean[] seen = new boolean[total];
    int count = 0;
    int curr = 0;
    for (int i = 0; i < s.length(); i++) {
        curr = ((curr << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[curr]) {
                seen[curr] = true;
                count++;
                if (count == total) {
                    return true;
                }
            }
        }
    }
    return false;
}

