public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int minSum = n;          // all 'a'
    int maxSum = 26 * n;     // all 'z'
    if (k < minSum || k > maxSum) {
        throw new IllegalArgumentException("k is out of valid range");
    }
    int remaining = k - minSum; // extra value to distribute
    char[] chars = new char[n];
    // start with all 'a'
    for (int i = 0; i < n; i++) {
        chars[i] = 'a';
    }
    // distribute from the end to keep lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // can increase up to 'z'
        chars[i] = (char) (chars[i] + add);
        remaining -= add;
    }
    return new String(chars);
}

