public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int bitCount = 0;
        int mask = 1 << i;
        for (int num : nums) {
            if ((num & mask) != 0) {
                bitCount++;
            }
        }
        if ((bitCount % 3) != 0) {
            result |= mask;
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (high < 0) {
        return result;
    }
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    Queue<Integer> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer(i);
    }
    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add(num);
        }
        int last = num % 10;
        if (last > 0) {
            long nextNum = (long) num * 10 + (last - 1);
            if (nextNum <= high) {
                queue.offer((int) nextNum);
            }
        }
        if (last < 9) {
            long nextNum = (long) num * 10 + (last + 1);
            if (nextNum <= high) {
                queue.offer((int) nextNum);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (n / factor > 0) {
        long lower = n - (n / factor) * factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false;
    }
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0] != null ? mat[0].length : 0;
    if (n == 0) {
        return 0;
    }

    int[][] left = new int[m][n];
    int[][] up = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int max = 0;

    for (int i = 0; i < m; i++) {
        if (mat[i] == null) {
            continue; // treat entire row as zeros
        }
        for (int j = 0; j < n; j++) {
            if (j >= mat[i].length || mat[i][j] != 1) {
                left[i][j] = up[i][j] = diag[i][j] = anti[i][j] = 0;
                continue;
            }
            left[i][j] = (j > 0 ? left[i][j - 1] : 0) + 1;
            up[i][j] = (i > 0 ? up[i - 1][j] : 0) + 1;
            diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
            anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
            int curMax = Math.max(Math.max(left[i][j], up[i][j]),
                                  Math.max(diag[i][j], anti[i][j]));
            if (curMax > max) {
                max = curMax;
            }
        }
    }
    return max;
}

public static String addThousandSeparator(int n) {
    // Handle zero explicitly
    if (n == 0) {
        return "0";
    }

    boolean negative = n < 0;
    // Work with absolute value to simplify processing
    int absValue = Math.abs(n);
    String numberStr = Integer.toString(absValue);

    StringBuilder sb = new StringBuilder();
    int count = 0;
    // Iterate from the end of the string to the beginning
    for (int i = numberStr.length() - 1; i >= 0; i--) {
        sb.append(numberStr.charAt(i));
        count++;
        // Insert dot after every three digits, except if it's the last group
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }

    // Reverse to get the correct order
    sb.reverse();

    // Prepend negative sign if necessary
    if (negative) {
        sb.insert(0, '-');
    }

    return sb.toString();
}

