public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = 0;
    stack[top] = -1; // sentinel
    long maxArea = 0;
    for (int i = 0; i < n; i++) {
        while (top > 0 && heights[i] < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = i - stack[top] - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    while (top > 0) {
        int height = heights[stack[top--]];
        int width = n - stack[top] - 1;
        long area = (long) height * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        if (sum % 2 == 0) {
            int row = Math.min(sum, m - 1);
            int col = sum - row;
            while (row >= 0 && col < n) {
                result[idx++] = mat[row][col];
                row--;
                col++;
            }
        } else {
            int col = Math.min(sum, n - 1);
            int row = sum - col;
            while (col >= 0 && row < m) {
                result[idx++] = mat[row][col];
                row++;
                col--;
            }
        }
    }
    return result;
}

